clear
close all

syms x x1 x2 
x1 = -2*pi:0.01:2*pi;
x2 = -pi:0.1:pi;

f1 = tan(sin(x1)) + sin(tan(x1));
f1(x1 >= -pi & x1 <= pi) = NaN;
f2 = tan(sin(x2)) + sin(tan(x2));

figure(1) %[output:4797c52c]
plot(x1, f1); %[output:4797c52c]
hold on %[output:4797c52c]
plot(x2, f2, 'Y'); %[output:4797c52c]
hold off %[output:4797c52c]
title('f(x) = tan(sin(x)) + sin(tan(x))') %[output:4797c52c]
legend('Intervalas [-2\pi, 2\pi] (be [-\pi, \pi])', 'Intervalas [-\pi, \pi], žingsnis 0.1 (geltona)'); %[output:4797c52c]
xlabel('x') %[output:4797c52c]
ylabel('y') %[output:4797c52c]
grid on %[output:4797c52c]

f3 = log(exp(-0.5*x));
f4 = sin(x);

figure(2) %[output:78123731]
fplot(f3); %[output:78123731]
hold on %[output:78123731]
fplot(f4); %[output:78123731]
hold off %[output:78123731]
title('f(x) = log(exp(-0.5*x) ir f(x) = sin(x)') %[output:78123731]
legend('f(x) = log(exp(1)^-0.5*x)', 'f(x) = sin(x)') %[output:78123731]
xlabel('x') %[output:78123731]
ylabel('y') %[output:78123731]
grid on %[output:78123731]
%%
clear
close all

syms N M

N = 10;
M = 10;

A = rand(N, M);
area(A) %[output:6305cc1b]
mesh(A) %[output:0940a2d6]
%%
clear
close all

A = 6; f = 2; sigma = 1.5; U1 = 4; U2 = 2;
t = 0:0.005:2;
n = sigma * randn(size(t));
s = A * cos(2*pi*f*t);
S = s + n;

UG = S > U1;
a3 = S(UG);

b3 = a3;
b3(abs(b3) < U2) = 0;

figure(3) %[output:3449fa64]
subplot(2, 1, 1) %[output:3449fa64]
plot(S,'r-.') %[output:3449fa64]
yline(U1, 'y', 'LineWidth', 2) %[output:3449fa64]
yline(U2)
subplot(2, 1, 2) %[output:3449fa64]
plot(b3, 'k') %[output:3449fa64]

